/** Whether an unseal error means the password is wrong (as opposed to a bad or expired token). */
function isBadPassword(error: unknown): boolean {
  return error instanceof Error && error.message === "Bad hmac value";
}

/**
 * Unseals with each password in order; `extra` is true when one after the first
 * opened it. Only a wrong password moves on to the next one, any other error
 * does not depend on the password and is thrown as is.
 */
async function unsealWithPasswords(
  sealed: string,
  passwords: string[],
  options: SealOptions,
): Promise<{ unsealed: Partial<Session>; extra: boolean }> {
  let lastError: unknown;
  for (const [index, password] of passwords.entries()) {
    try {
      const unsealed = (await unseal(sealed, password, options)) as Partial<Session>;
      return { unsealed, extra: index > 0 };
    } catch (error) {
      if (!isBadPassword(error)) {
        throw error;
      }
      lastError = error;
    }
  }
  throw lastError;
}
